+    border-radius: 4px;
+    padding: 2px 6px;
+    font-size: 0.8rem;
+    color: #dcddde;
+    cursor: pointer;
+    display: flex;
+    align-items: center;
+    gap: 4px;
+    transition: background-color 0.15s;
+}
+
+::deep .reaction-badge:hover {
+    background: #3c3f45;
+    border-color: #72767d;
+}
+
+/* ===== Thread Link ===== */
+::deep .thread-link {
+    background: none;
+    border: none;
+    color: #00aff4;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    font-weight: 500;
+}
+
+::deep .thread-link:hover {
+    text-decoration: underline;
+}
+
+/* ===== Message Hover Actions ===== */
+::deep .message-actions {
+    position: absolute;
+    top: -10px;
+    right: 12px;
+    display: flex;
+    gap: 2px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px;
+    z-index: 10;
+}
+
+::deep .action-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 0.75rem;
+    padding: 4px 8px;
+    cursor: pointer;
+    border-radius: 3px;
+    white-space: nowrap;
+}
+
+::deep .action-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+/* ===== Emoji Picker ===== */
+::deep .emoji-picker {
+    position: absolute;
+    top: -10px;
+    right: 12px;
+    transform: translateY(-100%);
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    z-index: 20;
+}
+
+::deep .emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+    transition: background-color 0.1s;
+}
+
+::deep .emoji-btn:hover {
+    background: #4f545c;
+}
+
+/* ===== Message Input ===== */
+::deep .message-input-area {
+    padding: 12px 20px;
+    display: flex;
+    gap: 8px;
+    border-top: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .message-textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    color: #dcddde;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+    outline: none;
+}
+
+::deep .message-textarea::placeholder {
+    color: #72767d;
+}
+
+::deep .message-textarea:focus {
+    outline: none;
+    box-shadow: 0 0 0 1px #5865f2;
+}
+
+::deep .btn-send {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 8px 16px;
+    font-size: 0.85rem;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+    transition: background-color 0.15s;
+}
+
+::deep .btn-send:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .btn-send:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* ===== Thread Panel ===== */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .btn-close-thread {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.1rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .btn-close-thread:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-divider {
+    padding: 8px 16px;
+    font-size: 0.75rem;
+    color: #72767d;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 16px;
+}
+
+/* ===== Scrollbar Styling ===== */
+::deep ::-webkit-scrollbar {
+    width: 8px;
+}
+
+::deep ::-webkit-scrollbar-track {
+    background: transparent;
+}
+
+::deep ::-webkit-scrollbar-thumb {
+    background: #202225;
+    border-radius: 4px;
+}
+
+::deep ::-webkit-scrollbar-thumb:hover {
+    background: #2e3338;
+}
+

